cat > orders.py <<'EOF'
def _validate_qty(qty):
    if qty <= 0:
        raise ValueError('qty must be positive')


def create(qty):
    _validate_qty(qty)
    return {'qty': qty}


def update(order, qty):
    _validate_qty(qty)
    order['qty'] = qty
    return order
EOF
